<script setup lang="ts">
import { ref, computed, onMounted, nextTick, onBeforeUnmount, watch } from 'vue'
import { LayoutDashboard, MessagesSquare, Workflow, Library, Network, Activity, Settings2, ArrowUpRight, ArrowRight, Plus, Search, Send, Paperclip, X, Check, LoaderCircle, FileText, Image as ImageIcon, Waves, ChevronLeft, ChevronRight, Download, CircleHelp, RefreshCw, Play, Square, CheckCircle2, ExternalLink, Menu, ScanEye, Sprout, Microscope, BookOpen, Braces, Clock3, PanelRightClose, Wrench, Globe, Terminal, FolderPen, Folder, FolderPlus, Pin, Store } from 'lucide-vue-next'
import { marked } from 'marked'
import DOMPurify from 'dompurify'
import type { ECharts } from 'echarts/core'
import crabArt from './crab.svg'

type Obj = Record<string, any>
const nav = [
 { id:'home', label:'智研总览', icon:LayoutDashboard, sub:'工作台' },
 { id:'chat', label:'知识问答', icon:MessagesSquare, sub:'多模态' },
 { id:'research', label:'研究任务', icon:Workflow, sub:'Agent' },
 { id:'documents', label:'知识资料', icon:Library, sub:'资料库' },
 { id:'graph', label:'图谱探索', icon:Network, sub:'关联' },
 { id:'market', label:'工具商店', icon:Store, sub:'MCP' },
 { id:'tools', label:'工具实验室', icon:Wrench, sub:'工具' },
 { id:'metrics', label:'运行观察', icon:Activity, sub:'监测' },
 { id:'settings', label:'连接设置', icon:Settings2, sub:'配置' }
]
const page = ref('chat'), mobileNav = ref(false), overview = ref<Obj>({}), config = ref<Obj>({})
const projects = ref<Obj[]>([]), projectId = ref(''), newProjectOpen = ref(false), projectName = ref('')
const marketTools = ref<Obj[]>([]), marketSearch = ref(''), marketCategory = ref('全部'), marketSaving = ref('')
const researchStages = ref<Obj[]>([]), researchStream = ref('')
const presets = ref<Obj[]>([]), presetId = ref('custom'), modelDraft = ref<Obj>({}), modelSaving = ref(false), graphSaving = ref(false)
const settingsOpen = ref(false), settingsTab = ref('settings'), settingsDialog = ref<HTMLElement>()
const settingsPages = ['settings','market','tools','documents','graph','metrics']
let previousFocus: HTMLElement|null = null
let previousOverflow = ''
let graphVersion = 0
const settingsNav = computed(()=>settingsPages.map(id=>nav.find(n=>n.id===id)!))
const pinnedItems = computed<Obj[]>(()=>[...projects.value.filter(p=>p.pinned).map(p=>({...p,kind:'project'})),...sessions.value.filter(p=>p.pinned).map(p=>({...p,kind:'session'}))])
const ordinaryChats = computed(()=>sessions.value.filter(p=>!p.pinned&&!p.project_id))
const projectChats = computed(()=>sessions.value.filter(p=>p.project_id===projectId.value))
const visibleTools = computed(()=>marketTools.value.filter(t=>(marketCategory.value==='全部'||t.category===marketCategory.value)&&(t.name+t.description).includes(marketSearch.value)))
const selectedProject = computed(()=>projects.value.find(p=>p.id===projectId.value))
const error = ref(''), toast = ref(''), loading = ref(false)
const sessions = ref<Obj[]>([]), sid = ref(''), messages = ref<Obj[]>([]), input = ref('')
const attachments = ref<Obj[]>([]), uploadBusy = ref(false), busy = ref(false), streamText = ref(''), stages = ref<Obj[]>([])
const currentJob = ref(''), currentResult = ref<Obj|null>(null), evidenceOpen = ref(true), selectedSource = ref('')
const goal = ref(''), reviewPlan = ref(true), jobs = ref<Obj[]>([]), activeTask = ref<Obj|null>(null), researchBusy = ref(false)
const docs = ref<Obj>({documents:[],pagination:{}}), docPage = ref(1), docStatus = ref(''), docSearch = ref('')
const graphLabel = ref('青蟹'), graphDepth = ref(1), graphLimit = ref(300), graphStats = ref<Obj>({}), graphLabels = ref<string[]>([]), graphData = ref<Obj>({nodes:[],edges:[]}), selectedNode = ref<Obj|null>(null)
const graphEl = ref<HTMLElement>(), chart = ref<ECharts>(), metrics = ref<Obj[]>([]), chatEnd = ref<HTMLElement>()
const selectedTool = ref('literature'), toolInput = ref('Scylla paramamosain water quality aquaculture'), toolBusy = ref(false), toolJob = ref<Obj|null>(null)
const toolCatalog = [
 {id:'literature',label:'联网文献检索',icon:Search,color:'mint',description:'检索 Crossref 公开书目信息，发现新的研究资料。',example:'Scylla paramamosain water quality aquaculture'},
 {id:'mcp_images',label:'MCP 图片检索',icon:ImageIcon,color:'peach',description:'通过真实 MCP 协议搜索 Wikimedia 参考图片与许可。',example:'Scylla paramamosain'},
 {id:'webpage',label:'公开网页抓取',icon:Globe,color:'blue',description:'提取白名单研究网站的正文，检查公开资料内容。',example:'https://en.wikipedia.org/wiki/Scylla_paramamosain'},
 {id:'download',label:'研究资源下载',icon:Download,color:'lavender',description:'下载公共研究站点的 PDF，保存到项目资源目录。',example:''},
 {id:'note',label:'研究笔记文件',icon:FolderPen,color:'mint',description:'保存 Markdown 笔记，记录研究目标与待核实信息。',example:'# 青蟹研究笔记\n\n记录需要核实的养殖条件和文献依据。'},
 {id:'terminal',label:'终端统计分析',icon:Terminal,color:'peach',description:'执行固定 Python 统计命令，分析用户提供的 CSV。',example:'timestamp,temperature,ph,dissolved_oxygen,salinity\n2026-10-01,26.5,7.8,5.2,20\n2026-10-02,27,7.9,5.5,21'}
]
let eventSource: EventSource|null = null
const mcpConfig = computed(()=>JSON.stringify({mcpServers:{crabgraph:{command:config.value.mcp_command,args:config.value.mcp_args}}},null,2))
const counts = computed(()=>overview.value.documents?.status_counts || {})
const activeTitle = computed(()=>page.value==='project'?selectedProject.value?.title:page.value==='chat'?'对话':nav.find(n=>n.id===page.value)?.label)
const filteredDocs = computed(()=>(docs.value.documents || []).filter((d:Obj)=>(d.file_path||'').toLowerCase().includes(docSearch.value.toLowerCase())))
const sources = computed(()=>currentResult.value?.sources || [])
const snippets = computed(()=>(currentResult.value?.evidence || []).filter((e:Obj)=>!selectedSource.value || e.source_id===selectedSource.value))
const researchJobs = computed(()=>jobs.value.filter(j=>j.kind==='research'))
const examples = [
 { icon:Sprout, label:'养殖管理', text:'青蟹养殖中，水质管理需要关注哪些指标？请给出资料依据。', color:'mint' },
 { icon:ScanEye, label:'图文观察', text:'结合上传图片描述青蟹可见特征，并说明还需要补充哪些信息。', color:'peach' },
 { icon:Microscope, label:'病害研究', text:'青蟹病害排查需要收集哪些现场信息？单张图片有哪些判断局限？', color:'lavender' },
 { icon:BookOpen, label:'文献比较', text:'比较 Scylla paramamosain 与 Scylla serrata，说明文献中的主要区别。', color:'blue' }
]
function html(text:string){ const rendered=(marked.parse(text || '',{async:false}) as string).replace(/\[(S\d+)\]/g,'<a class="citation" href="#source-$1" data-source="$1">[$1]</a>');return DOMPurify.sanitize(rendered, { FORBID_TAGS:['img','iframe'], FORBID_ATTR:['style'] }) }
function selectCitation(event:MouseEvent){const link=(event.target as HTMLElement).closest('[data-source]') as HTMLElement|null;if(!link)return;event.preventDefault();selectedSource.value=link.dataset.source||'';evidenceOpen.value=true;if(page.value==='research')document.getElementById('source-'+selectedSource.value)?.scrollIntoView({behavior:'smooth',block:'center'})}
function basename(path:string){ return (path||'来源文件').split(/[\\/]/).pop() || path }
function time(t:number){ return new Date(t*1000).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}) }
function duration(ms:number){ return typeof ms==='number'?(ms/1000).toFixed(1)+' s':'—' }
function status(s:string){ return ({queued:'排队中',running:'执行中',awaiting_approval:'待确认计划',completed:'已完成',failed:'执行失败',cancelled:'已取消',processed:'已入库',processing:'处理中',analyzing:'分析中',parsing:'解析中',pending:'待处理',preprocessed:'已预处理'} as Obj)[s]||s }
async function api(path:string, options:RequestInit={}){
 const r = await fetch('/api'+path,options)
 if(!r.ok){let detail='请求失败';try{const v=await r.json();detail=typeof v.detail==='string'?v.detail:'输入参数不符合要求'}catch{} throw new Error(detail)}
 return r.json()
}
function post(path:string,data:Obj={}){ return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}) }
function notify(text:string){ toast.value=text; setTimeout(()=>toast.value='',3500) }
async function protect(fn:()=>Promise<void>){ error.value='';try{await fn()}catch(e){error.value=(e as Error).message} }
async function navigate(id:string){
 if(settingsTab.value==='graph'&&id!=='graph')disposeGraph()
 if(settingsPages.includes(id)){if(!settingsOpen.value)previousFocus=document.activeElement as HTMLElement;settingsOpen.value=true;settingsTab.value=id}else{settingsOpen.value=false;page.value=id}
 mobileNav.value=false;error.value=''
 await protect(async()=>{
  loading.value=true
  if(id==='home') overview.value=await api('/overview')
  if(id==='chat'){sessions.value=await api('/sessions');if(!busy.value&&sid.value)await openSession(sid.value)}
  if(id==='research'){jobs.value=await api('/jobs');if(!activeTask.value&&researchJobs.value.length) await openTask(researchJobs.value[0].id)}
  if(id==='documents')await loadDocs()
  if(id==='graph'){graphLabels.value=await api('/graph/labels');graphStats.value=await api('/graph/stats');await loadGraph()}
  if(id==='metrics'){metrics.value=await api('/metrics');jobs.value=await api('/jobs')}
  if(id==='market'||id==='tools')marketTools.value=(await api('/tool-store')).tools
  if(id==='settings'){config.value=await api('/config');presets.value=await api('/config/presets');modelDraft.value={...config.value,api_key:''};presetId.value='custom'}
 });loading.value=false;await nextTick();if(settingsOpen.value)settingsDialog.value?.querySelector('.settings-body')?.scrollTo({top:0,behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'})
}
async function newSession(parent?:string){if(busy.value)return;const r=await post('/sessions');sid.value=r.id;if(parent)await api(`/sidebar/session/${r.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:parent,pinned:false})});messages.value=[];currentResult.value=null;streamText.value='';stages.value=[];currentJob.value='';attachments.value=[];sessions.value=await api('/sessions');page.value='chat'}
async function selectAnswer(payload:Obj){currentResult.value=payload;selectedSource.value='';currentJob.value='';stages.value=[];const list=await api('/jobs');const j=list.find((j:Obj)=>j.kind==='chat'&&j.session_id===sid.value&&j.result?.metrics?.run_id===payload.metrics?.run_id);if(j){currentJob.value=j.id;stages.value=(await api(`/jobs/${j.id}`)).events.filter((e:Obj)=>['stage','retrieval','observation'].includes(e.type))}}
async function openSession(id:string){if(busy.value)return;sid.value=id;messages.value=await api(`/sessions/${id}/messages`);const result=[...messages.value].reverse().find(m=>m.role==='assistant')?.payload;currentResult.value=null;selectedSource.value='';stages.value=[];streamText.value='';currentJob.value='';if(result)await selectAnswer(result);const j=(await api('/jobs')).find((j:Obj)=>j.session_id===id&&['queued','running'].includes(j.status));if(j){busy.value=true;currentJob.value=j.id;stages.value=[];subscribe(j.id,'chat')}await scrollChat()}
async function showSession(id:string){page.value='chat';mobileNav.value=false;await protect(()=>openSession(id))}
async function showProject(id:string){projectId.value=id;await navigate('project')}
async function refreshSidebar(){[sessions.value,projects.value]=await Promise.all([api('/sessions'),api('/projects')])}
async function pinItem(kind:string,item:Obj){await protect(async()=>{await api(`/sidebar/${kind}/${item.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({pinned:!item.pinned,project_id:item.project_id||null})});await refreshSidebar()})}
async function createProject(){if(!projectName.value.trim())return;await protect(async()=>{const r=await post('/projects',{title:projectName.value.trim()});newProjectOpen.value=false;projectName.value='';await refreshSidebar();await showProject(r.id)})}
async function toggleTool(t:Obj){marketSaving.value=t.id;await protect(async()=>{marketTools.value=(await api(`/tool-store/${t.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:!t.enabled})})).tools;notify(t.enabled?'工具已停用':'工具已启用')});marketSaving.value=''}
function usePreset(){const p=presets.value.find(p=>p.id===presetId.value);if(p&&p.id!=='custom')modelDraft.value={...p,api_key:''}}
async function toggleGraph(){graphSaving.value=true;await protect(async()=>{config.value=await api('/config/retrieval',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({knowledge_graph_enabled:!config.value.knowledge_graph_enabled})})});graphSaving.value=false}
async function saveModel(){modelSaving.value=true;await protect(async()=>{config.value=await api('/config/model',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({base_url:modelDraft.value.base_url,model:modelDraft.value.model,vision_model:modelDraft.value.vision_model,api_key:modelDraft.value.api_key||null})});modelDraft.value={...config.value,api_key:''};notify('模型配置已保存，下一次任务生效')});modelSaving.value=false}
async function scrollChat(){ await nextTick();chatEnd.value?.scrollIntoView({behavior:'smooth',block:'end'}) }
async function upload(files:FileList|null){if(!files)return;await protect(async()=>{uploadBusy.value=true;for(const file of Array.from(files).slice(0,2)){const form=new FormData();form.append('file',file);const r=await api('/attachments',{method:'POST',body:form});attachments.value=attachments.value.filter(a=>a.kind!==r.kind);attachments.value.push(r)} });uploadBusy.value=false}
async function send(){if(busy.value||researchBusy.value||toolBusy.value||uploadBusy.value||!input.value.trim())return;await protect(async()=>{
 const attached=[...attachments.value];if(!sid.value)await newSession();const question=input.value.trim();const payload={session_id:sid.value,question,image_id:attached.find(a=>a.kind==='image')?.id,csv_id:attached.find(a=>a.kind==='csv')?.id}
 const j=await post('/chat',payload);currentJob.value=j.id;messages.value.push({role:'user',payload:{text:question,...payload}});input.value='';attachments.value=[];busy.value=true;streamText.value='';stages.value=[];currentResult.value=null;subscribe(j.id,'chat');await scrollChat()
})}
function subscribe(id:string,kind:string,after=0){
 eventSource?.close();eventSource=new EventSource(`/api/jobs/${id}/events?after=${after}`)
 eventSource.onmessage=(ev)=>{
  const e=JSON.parse(ev.data)
  if(e.type==='stage'||e.type==='retrieval'||e.type==='observation')(kind==='chat'?stages:researchStages).value.push(e)
  if(e.type==='token'){(kind==='chat'?streamText:researchStream).value+=e.text;if(kind==='chat')void scrollChat()}
  if(e.type==='plan'&&activeTask.value)activeTask.value.result={plan:e.plan}
  if(e.type==='result'){if(kind==='chat'){currentResult.value=e;streamText.value='';messages.value.push({role:'assistant',payload:e});void scrollChat()}else if(activeTask.value){researchStream.value='';activeTask.value.result=e;activeTask.value.status='completed'}}
  if(e.type==='error')error.value=e.text
 }
 eventSource.addEventListener('done',async(ev)=>{
  eventSource?.close();eventSource=null;busy.value=false;researchBusy.value=false
  if(kind==='chat')sessions.value=await api('/sessions')
  else {activeTask.value=await api(`/jobs/${id}`);jobs.value=await api('/jobs')}
 })
 eventSource.onerror=()=>{if(eventSource?.readyState===EventSource.CLOSED){busy.value=false;researchBusy.value=false;error.value='连接已关闭，打开运行记录可查看任务结果。'}}
}
async function startResearch(){if(researchBusy.value||busy.value||toolBusy.value||!goal.value.trim())return;await protect(async()=>{
 const j=await post('/research',{goal:goal.value,review_plan:reviewPlan.value,csv_id:attachments.value.find(a=>a.kind==='csv')?.id});activeTask.value=await api(`/jobs/${j.id}`);researchBusy.value=true;researchStages.value=[];researchStream.value='';subscribe(j.id,'research');jobs.value=await api('/jobs')
})}
async function openTask(id:string){if(researchBusy.value||busy.value){error.value='请先等待当前任务完成或取消';return}activeTask.value=await api(`/jobs/${id}`);researchStages.value=activeTask.value?.events?.filter((e:Obj)=>['stage','retrieval'].includes(e.type))||[];researchStream.value='';if(['running','queued'].includes(activeTask.value?.status)){researchBusy.value=true;subscribe(id,'research',activeTask.value?.events?.at(-1)?.id||0)}}
async function approveTask(){if(!activeTask.value)return;await protect(async()=>{await post(`/jobs/${activeTask.value!.id}/approve`);activeTask.value!.status='running';researchBusy.value=true;subscribe(activeTask.value!.id,'research',activeTask.value!.events?.at(-1)?.id||0)})}
async function cancelTask(){const id=page.value==='research'?activeTask.value?.id:currentJob.value;if(!id)return;await protect(async()=>{await post(`/jobs/${id}/cancel`);notify('已请求取消，网络调用返回后停止')})}
async function loadDocs(){docs.value=await api(`/documents?page=${docPage.value}${docStatus.value?'&status='+docStatus.value:''}`)}
async function uploadDocument(files:FileList|null){if(!files?.[0])return;await protect(async()=>{uploadBusy.value=true;const form=new FormData();form.append('file',files[0]);await api('/documents/upload',{method:'POST',body:form});notify('文件已提交到项目知识库，请等待解析入库');await loadDocs()});uploadBusy.value=false}
function disposeGraph(){graphVersion++;chart.value?.dispose();chart.value=undefined}
async function loadGraph(){const version=++graphVersion;const echarts=await import('./graph-engine');selectedNode.value=null;const data=await api(`/graph?label=${encodeURIComponent(graphLabel.value)}&depth=${graphDepth.value}&max_nodes=${graphLimit.value}`);if(version!==graphVersion||!settingsOpen.value||settingsTab.value!=='graph')return;graphData.value=data;await nextTick();if(version!==graphVersion||!settingsOpen.value||settingsTab.value!=='graph'||!graphEl.value)return;if(chart.value)chart.value.dispose();chart.value=echarts.init(graphEl.value);const nodes=graphData.value.nodes||[];const edges=graphData.value.edges||[];chart.value.setOption({tooltip:{trigger:'item',formatter:(p:any)=>p.data?.name||'关系'},animation:false,series:[{type:'graph',layout:'force',roam:true,draggable:true,zoom:Math.min(1,Math.min(graphEl.value.clientWidth,graphEl.value.clientHeight)/60/Math.sqrt(Math.max(nodes.length,1))),scaleLimit:{min:.05,max:4},force:{layoutAnimation:false,repulsion:270,edgeLength:[70,145],gravity:.07},data:nodes.map((n:Obj,i:number)=>({id:String(n.id),name:String(n.labels?.[0]||n.id),symbolSize:n.id===graphLabel.value?48:18+(i%3)*6,itemStyle:{color:['#208779','#e7b879','#99baba','#b7a5cc'][i%4]},label:{show:i<20,fontSize:11,color:'#334f4c'},raw:n})),links:edges.map((e:Obj)=>({source:String(e.source),target:String(e.target),name:e.properties?.keywords||'关联'})),lineStyle:{color:'#b4cebf',opacity:.65,curveness:.08},emphasis:{focus:'adjacency',lineStyle:{width:3}},label:{position:'right'}}]});chart.value.on('click',(p:any)=>{if(p.data?.raw)selectedNode.value=p.data.raw})}
function closeSettings(){disposeGraph();settingsOpen.value=false;error.value=''}
function settingsKeys(e:KeyboardEvent){if(e.key==='Escape'){if(newProjectOpen.value){newProjectOpen.value=false;return}if(settingsOpen.value){closeSettings();e.preventDefault()}}if(settingsOpen.value&&e.key==='Tab'){const elements=Array.from(settingsDialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input,select,textarea')||[]).filter(el=>el.getClientRects().length);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}}
watch(settingsOpen,async(open)=>{if(open){previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();settingsDialog.value?.querySelector<HTMLElement>('.settings-close')?.focus()}else{document.body.style.overflow=previousOverflow;previousFocus?.focus();await nextTick();resize()}})
function resize(){if(settingsOpen.value&&settingsTab.value==='graph')chart.value?.resize()}
async function runTool(){if(toolBusy.value||researchBusy.value||busy.value||!toolInput.value.trim())return;await protect(async()=>{toolBusy.value=true;const j=await post('/tools',{tool:selectedTool.value,input:toolInput.value});toolJob.value=await api(`/jobs/${j.id}`);const es=new EventSource(`/api/jobs/${j.id}/events`);es.onmessage=(ev)=>{const e=JSON.parse(ev.data);if(e.type==='result'&&toolJob.value){toolJob.value.result=e;toolJob.value.status='completed'}if(e.type==='error')error.value=e.text};es.addEventListener('done',async()=>{es.close();toolJob.value=await api(`/jobs/${j.id}`);toolBusy.value=false});es.onerror=()=>{if(es.readyState===EventSource.CLOSED){toolBusy.value=false;error.value='工具事件连接已关闭，请查看运行记录。'}}});if(error.value)toolBusy.value=false}
onMounted(async()=>{evidenceOpen.value=window.innerWidth>=1000;window.addEventListener('resize',resize);window.addEventListener('keydown',settingsKeys);await protect(async()=>{config.value=await api('/config');overview.value=await api('/overview');await refreshSidebar()})})
onBeforeUnmount(()=>{eventSource?.close();disposeGraph();document.body.style.overflow=previousOverflow;window.removeEventListener('resize',resize);window.removeEventListener('keydown',settingsKeys)})
</script>

<template>
 <div class="shell" :inert="settingsOpen">
  <aside class="sidebar" :class="{open:mobileNav}">
   <a class="brand" href="#" @click.prevent="navigate('home')"><span class="brand-mark"><Network :size="25"/></span><span>CrabGraph<small>青蟹智研工作台</small></span></a>
   <button class="button primary full new-chat" :disabled="busy" @click="protect(()=>newSession())"><Plus :size="18"/>新对话</button>
   <div class="sidebar-items">
    <section v-if="pinnedItems.length" class="sidebar-group"><h3>置顶</h3><div v-for="item in pinnedItems" :key="item.id" class="sidebar-row"><button class="item-open" @click="item.kind==='project'?showProject(item.id):showSession(item.id)"><Folder v-if="item.kind==='project'" :size="17"/><MessagesSquare v-else :size="17"/><span>{{item.title}}</span></button><button class="pin-button pinned" aria-label="取消置顶" @click="pinItem(item.kind,item)"><Pin :size="14"/></button></div></section>
    <section class="sidebar-group"><h3>对话</h3><div v-for="item in ordinaryChats" :key="item.id" class="sidebar-row" :class="{selected:page==='chat'&&sid===item.id}"><button class="item-open" :disabled="busy" @click="showSession(item.id)"><MessagesSquare :size="17"/><span>{{item.title}}</span></button><button class="pin-button" aria-label="置顶对话" @click="pinItem('session',item)"><Pin :size="14"/></button></div><p v-if="!ordinaryChats.length" class="sidebar-empty">从新对话开始</p></section>
    <section class="sidebar-group"><h3>项目<button class="icon" aria-label="新建项目" @click="newProjectOpen=true"><FolderPlus :size="17"/></button></h3><div v-for="item in projects.filter(p=>!p.pinned)" :key="item.id" class="sidebar-row" :class="{selected:page==='project'&&projectId===item.id}"><button class="item-open" @click="showProject(item.id)"><Folder :size="17"/><span>{{item.title}}</span></button><button class="pin-button" aria-label="置顶项目" @click="pinItem('project',item)"><Pin :size="14"/></button></div><button v-if="!projects.length" class="text-button" @click="newProjectOpen=true">新建项目</button></section>
   </div>
   <div class="sidebar-bottom"><button class="profile full" aria-label="打开设置" @click="navigate('settings')"><span>CG</span><div>我的工作空间</div><Settings2 :size="18"/></button></div>
  </aside>
  <main>
   <header class="topbar"><div class="breadcrumbs"><button class="icon mobile-menu" @click="mobileNav=!mobileNav"><Menu :size="20"/></button><span>工作空间</span><ChevronRight :size="14"/><strong>{{activeTitle}}</strong></div><div class="top-actions"><span class="model-badge"><span class="status-dot"/>{{config.model||'DeepSeek'}}</span><a class="icon" title="查看使用说明" href="/guide/project-guide.html" target="_blank" rel="noopener"><CircleHelp :size="19"/></a><button class="avatar" aria-label="头像设置" @click="navigate('settings')">研</button></div></header>

   <div v-if="newProjectOpen" class="dialog-backdrop" @click.self="newProjectOpen=false"><form class="project-dialog panel" @submit.prevent="createProject"><div class="section-heading"><h2>新建项目</h2><button type="button" class="icon" aria-label="关闭新建项目" @click="newProjectOpen=false"><X :size="18"/></button></div><input v-model="projectName" aria-label="项目名称" placeholder="项目名称，例如：青蟹水质研究" maxlength="60"/><button class="button primary full" type="submit">创建项目</button></form></div>
   <div v-if="error&&!settingsOpen" class="error-banner" role="alert"><CircleHelp :size="18"/>{{error}}<button class="icon" @click="error=''" aria-label="关闭错误"><X :size="16"/></button></div>
   <div v-if="toast" class="toast" role="status"><CheckCircle2 :size="18"/>{{toast}}</div>

   <div v-if="page==='home'" class="content home">
    <div class="page-heading"><div><h1>让青蟹知识，产生新的连接<span class="title-dot">。</span></h1><p>从一张图片、一个问题，到有据可查的业务洞察。</p></div><button class="button light" @click="navigate('graph')"><Network :size="17"/>探索知识图谱<ArrowUpRight :size="16"/></button></div>
    <section class="hero"><div class="hero-copy"><span class="hero-label"><span/> 青蟹多模态研究助手</span><h2>问题有线索<br>研究有依据</h2><p>连接养殖资料、图像观察与知识图谱。<br>让智能体帮你检索、分析并整理研究报告。</p><button class="button cream" @click="navigate('chat')">开始一次知识问答<ArrowRight :size="17"/></button></div><img :src="crabArt" alt="由知识节点连接的青蟹插画"/><div class="floating-tag tag-one"><Network :size="17"/>图谱与原文联合检索</div><div class="floating-tag tag-two"><FileText :size="17"/>结论附带来源</div></section>
    <section class="stat-grid"><div class="stat-card"><span class="stat-icon mint"><Library :size="20"/></span><div><span>知识资料</span><strong>{{counts.all??'—'}}<small>份</small></strong></div></div><div class="stat-card"><span class="stat-icon blue"><MessagesSquare :size="20"/></span><div><span>研究会话</span><strong>{{overview.sessions??'—'}}<small>个</small></strong></div></div><div class="stat-card"><span class="stat-icon peach"><Workflow :size="20"/></span><div><span>完成任务</span><strong>{{overview.completed??'—'}}<small>次</small></strong></div></div><div class="stat-card"><span class="stat-icon lavender"><ScanEye :size="20"/></span><div><span>图文问答</span><strong class="stat-word">多模态</strong></div></div></section>
    <div class="section-heading"><h2>从这里开始探索</h2><span>四种方式，发现资料的价值</span></div><div class="explore-grid"><button v-for="ex in examples" :key="ex.label" class="explore-card" @click="navigate('chat');input=ex.text"><span class="feature-icon" :class="ex.color"><component :is="ex.icon" :size="23"/></span><ArrowUpRight class="card-arrow" :size="18"/><h3>{{ex.label}}</h3><p>{{ex.text}}</p><span class="card-link">试试这个问题 <ArrowRight :size="14"/></span></button></div>
    <div class="home-lower"><section class="panel recent"><div class="section-heading"><h2>最近的研究足迹</h2><button class="text-button" @click="navigate('metrics')">全部记录<ArrowRight :size="14"/></button></div><div v-if="!overview.recent?.length" class="empty-inline"><Waves :size="32"/><p>你的第一次研究，即将从这里开始。</p><button class="text-button" @click="navigate('research')">创建研究任务</button></div><div v-for="j in overview.recent" :key="j.id" class="recent-row"><span class="mini-icon"><component :is="j.kind==='research'?Workflow:MessagesSquare" :size="17"/></span><div><strong>{{j.payload.goal||j.payload.question||toolCatalog.find(t=>t.id===j.payload.tool)?.label||'工具运行'}}</strong><small>{{time(j.created)}} · {{j.kind==='research'?'研究任务':j.kind==='tool'?'工具运行':'知识问答'}}</small></div><span class="pill" :class="j.status">{{status(j.status)}}</span></div></section><section class="tip-card"><Sprout :size="36"/><h3>先观察，再求证</h3><p>图片提供可见线索，文献提供知识依据。结合环境与养殖记录，才能提出更可靠的研究问题。</p><button class="text-button" @click="navigate('chat')">上传图片开始观察<ArrowUpRight :size="15"/></button></section></div>
    
   </div>

   <div v-else-if="page==='chat'" class="chat-layout">

    <section class="chat-main"><div class="chat-toolbar"><div><span class="status-dot"/><strong>青蟹知识助手</strong></div><button class="icon" title="切换证据面板" @click="evidenceOpen=!evidenceOpen"><PanelRightClose :size="19"/></button></div>
     <div class="messages">
      <div v-if="!messages.length&&!busy" class="chat-welcome"><span class="welcome-symbol"><Waves :size="34"/></span><h2>今天，想了解青蟹的什么？</h2><p>问一个业务问题，或上传图片寻找线索。<br>我会帮你连接知识与证据。</p><div class="prompt-grid"><button v-for="ex in examples" :key="ex.label" @click="input=ex.text"><component :is="ex.icon" :size="18"/><span>{{ex.label}}<small>{{ex.text}}</small></span><ArrowUpRight :size="15"/></button></div><div class="welcome-note"><CheckCircle2 :size="14"/>回答附带原文来源，可在右侧核查证据</div></div>
      <article v-for="(m,index) in messages" :key="index" class="message" :class="m.role"><span class="message-avatar"><Network v-if="m.role==='assistant'" :size="18"/><span v-else>你</span></span><div class="message-body"><div class="message-label">{{m.role==='assistant'?'CrabGraph 青蟹智研':'我的问题'}}</div><template v-if="m.role==='user'"><p>{{m.payload.text}}</p><img v-if="m.payload.image_id" :src="`/api/attachments/${m.payload.image_id}`" class="message-image" alt="用户上传的观察图片"/><span v-if="m.payload.csv_id" class="attachment-chip"><FileText :size="14"/>养殖记录 CSV</span></template><template v-else><div class="markdown" @click="protect(()=>selectAnswer(m.payload)).then(()=>selectCitation($event))" v-html="html(m.payload.answer)"/><div class="message-meta"><span>{{m.payload.metrics?.model}}</span><span>{{duration(m.payload.metrics?.elapsed_ms)}}</span><button class="text-button" @click="protect(()=>selectAnswer(m.payload));evidenceOpen=true">{{m.payload.sources?.length||0}} 个来源 <ArrowUpRight :size="14"/></button></div></template></div></article>
      <article v-if="busy" class="message assistant"><span class="message-avatar"><LoaderCircle class="spin" :size="18"/></span><div class="message-body"><div class="message-label">{{stages.at(-1)?.text||'正在启动研究'}}</div><div v-if="streamText" class="markdown" v-html="html(streamText)"/><div v-else class="thinking-dots"><i/><i/><i/></div></div></article><div ref="chatEnd"/>
     </div>
     <div class="composer-wrap"><div v-if="attachments.length" class="attachment-row"><div v-for="a in attachments" :key="a.id" class="attachment-preview"><img v-if="a.kind==='image'" :src="`/api/attachments/${a.id}`" alt="待发送图片预览"/><FileText v-else :size="20"/><span>{{a.name}}</span><button class="icon" @click="attachments=attachments.filter(x=>x.id!==a.id)"><X :size="14"/></button></div></div><div class="composer"><textarea v-model="input" aria-label="输入青蟹业务问题" placeholder="描述你的青蟹业务问题，或者从一张图片开始…" @keydown.enter.exact.prevent="send"/><div class="composer-tools"><div><label class="upload-control" title="上传图片或 CSV"><Paperclip :size="19"/><input type="file" accept="image/png,image/jpeg,image/webp,.csv" multiple :disabled="busy||uploadBusy" @change="upload(($event.target as HTMLInputElement).files)"/></label></div><button v-if="busy" class="send-button" @click="cancelTask" aria-label="停止生成"><Square :size="17"/></button><button v-else class="send-button" :disabled="!input.trim()||uploadBusy" @click="send" aria-label="发送问题"><LoaderCircle v-if="uploadBusy" class="spin" :size="18"/><Send v-else :size="18"/></button></div></div><p class="composer-note">Enter 发送 · Shift + Enter 换行 · 图片观察不能替代现场诊断</p></div>
    </section>
    <aside v-if="evidenceOpen" class="evidence-panel"><div class="section-heading"><h3>证据与执行</h3><span class="count-badge">{{sources.length}}</span></div><div class="evidence-tabs"><span>来源资料</span><small>可追溯</small></div><div v-if="!sources.length" class="evidence-empty"><Network :size="40"/><h4>每个结论都有来处</h4><p>完成问答后，原文片段、来源文件与执行过程会在这里展开。</p><div class="evidence-flow"><span>提问</span><ArrowRight :size="14"/><span>检索</span><ArrowRight :size="14"/><span>证据</span></div></div><button v-for="s in sources" :key="s.id" class="source-card" :class="{chosen:selectedSource===s.id}" @click="selectedSource=selectedSource===s.id?'':s.id"><span class="source-id">{{s.id}}</span><strong>{{basename(s.file_path)}}</strong><FileText :size="15"/></button><details v-for="(e,i) in snippets.slice(0,10)" :key="i" class="snippet"><summary>{{e.source_id}} · 原文片段</summary><p>{{e.content}}</p></details><div v-if="stages.length" class="execution"><h4>本轮执行轨迹</h4><div v-for="(s,i) in stages" :key="i" class="trace-row"><span/><p>{{s.text||`${s.chunks} 个片段 / ${s.sources} 个来源`}}</p></div></div><div v-if="currentResult?.metrics" class="metric-mini"><span>检索片段<strong>{{currentResult.metrics.retrieved_chunks??snippets.length}}</strong></span><span>首字耗时<strong>{{duration(currentResult.metrics.first_token_ms)}}</strong></span><span>输入 Token<strong>{{currentResult.metrics.input_tokens??'—'}}</strong></span></div><a v-if="currentJob&&currentResult" :href="`/api/jobs/${currentJob}/report`" class="button light full"><Download :size="16"/>导出本轮回答</a></aside>
   </div>

   <div v-else-if="page==='research'" class="content">
    <div class="page-heading"><div><h1>把一个目标，交给研究智能体</h1><p>规划、检索、整理、检查引用。每一步都有执行记录。</p></div><span class="outline-tag"><Workflow :size="16"/>LangGraph 工作流</span></div>
    <div class="research-layout"><section class="research-left"><div class="panel task-composer"><div class="section-heading"><h2>新建研究任务</h2><span class="feature-icon peach"><Workflow :size="20"/></span></div><label class="field-label" for="goal">你希望解决什么业务问题？</label><textarea id="goal" v-model="goal" placeholder="例如：整理青蟹水质管理的文献依据，列出关键指标、监测方法与仍需核实的问题。"/><div class="goal-suggestions"><button @click="goal='整理青蟹水质管理的文献依据，列出主要指标、资料中的研究结论和仍需核实的现场信息。'">水质管理研究</button><button @click="goal='比较青蟹主要养殖种的形态特征与文献依据，明确图片识别的局限。'">物种比较研究</button></div><label class="checkbox"><input v-model="reviewPlan" type="checkbox"/><span>执行前由我确认计划<small>计划持久化保存，确认后继续执行</small></span></label><div class="attachment-row"><span v-for="a in attachments.filter(a=>a.kind==='csv')" :key="a.id" class="attachment-chip"><FileText :size="14"/>{{a.name}}<button class="icon" @click="attachments=attachments.filter(x=>x.id!==a.id)"><X :size="13"/></button></span></div><div class="task-actions"><label class="text-button upload-control"><Paperclip :size="16"/>附加 CSV<input type="file" accept=".csv" @change="upload(($event.target as HTMLInputElement).files)"/></label><button class="button primary" :disabled="researchBusy||!goal.trim()||uploadBusy" @click="startResearch"><LoaderCircle v-if="researchBusy" class="spin" :size="16"/><Play v-else :size="16"/>开始研究</button></div></div><section class="panel task-history"><div class="section-heading"><h2>研究任务</h2><span class="count-badge">{{researchJobs.length}}</span></div><p v-if="!researchJobs.length" class="muted">提交第一个研究目标，建立你的业务报告。</p><button v-for="j in researchJobs" :key="j.id" class="task-item" :class="{selected:activeTask?.id===j.id}" @click="protect(()=>openTask(j.id))"><span class="pill" :class="j.status">{{status(j.status)}}</span><strong>{{j.payload.goal}}</strong><small>{{time(j.created)}}<ArrowUpRight :size="14"/></small></button></section></section>
    <section class="panel task-detail"><div class="section-heading"><h2>{{activeTask?'研究执行台':'一份报告是怎样形成的'}}</h2><button v-if="researchBusy" class="text-button danger" @click="cancelTask"><Square :size="14"/>取消任务</button><span v-else-if="activeTask" class="pill" :class="activeTask.status">{{status(activeTask.status)}}</span></div><div class="workflow-strip"><div v-for="(s,i) in ['目标拆解','计划确认','证据检索','报告整理','引用检查']" :key="s"><span>{{String(i+1).padStart(2,'0')}}</span><strong>{{s}}</strong><ChevronRight v-if="i<4" :size="15"/></div></div><div v-if="!activeTask" class="task-empty"><img :src="crabArt" alt="青蟹研究图示"/><h3>让研究过程清晰可见</h3><p>输入业务目标后，智能体会先给出研究计划，<br>再从知识库检索证据，形成可导出的报告。</p><div class="task-empty-tags"><span><Check :size="14"/>来源追溯</span><span><Check :size="14"/>计划审批</span><span><Check :size="14"/>报告导出</span></div></div><template v-else><h3 class="task-goal">{{activeTask.payload.goal}}</h3><div v-if="activeTask.result?.plan" class="plan-card"><h3>{{activeTask.result.plan.title}}</h3><p>{{activeTask.result.plan.approach}}</p><ol><li v-for="q in activeTask.result.plan.queries" :key="q">{{q}}</li></ol><button v-if="activeTask.status==='awaiting_approval'" class="button primary" @click="approveTask"><Check :size="16"/>确认计划并继续执行</button></div><div v-if="researchStages.length" class="research-trace"><div v-for="(s,i) in researchStages" :key="i" class="trace-row"><CheckCircle2 :size="15"/><p>{{s.text||`${s.query} → ${s.chunks} 个片段，${s.sources} 个来源`}}</p></div></div><div v-if="researchStream||activeTask.result?.answer" class="report-paper"><div class="report-label"><FileText :size="17"/>研究报告<span v-if="researchBusy">正在生成</span></div><div class="markdown" @click="selectCitation" v-html="html(researchStream||activeTask.result.answer)"/><div v-if="activeTask.status==='completed'" class="report-downloads"><a class="button primary" :href="`/api/jobs/${activeTask.id}/report?format=pdf`"><Download :size="16"/>下载 PDF</a><a class="button light" :href="`/api/jobs/${activeTask.id}/report`">Markdown</a><span>{{activeTask.result.sources?.length||0}} 个来源 · {{duration(activeTask.result.metrics?.elapsed_ms)}}</span></div><div v-if="activeTask.result?.sources" class="report-sources"><strong>参考来源</strong><p v-for="s in activeTask.result.sources" :key="s.id" :id="'source-'+s.id" :class="{chosen:selectedSource===s.id}">[{{s.id}}] {{basename(s.file_path)}}</p></div></div><div v-if="activeTask.status==='failed'||activeTask.status==='cancelled'" class="empty-inline"><CircleHelp :size="30"/><p>{{activeTask.status==='failed'?'任务执行失败，可调整目标后重新提交。':'该任务已取消。'}}</p><button class="text-button" @click="goal=activeTask.payload.goal">使用此目标重新研究</button></div></template></section></div>
   </div>

   <div v-else-if="page==='project'" class="content"><div class="page-heading"><div><h1>{{selectedProject?.title}}</h1><p>把相关对话放在一起，继续你的研究。</p></div><button class="button primary" @click="protect(()=>newSession(projectId))"><Plus :size="17"/>项目新对话</button></div><div class="project-actions"><button class="button light" @click="navigate('research')"><Workflow :size="17"/>创建研究任务</button><button class="button light" @click="navigate('documents')"><Library :size="17"/>知识资料</button></div><section class="panel"><h2>项目对话</h2><div v-for="item in projectChats" :key="item.id" class="project-chat-row"><button @click="showSession(item.id)"><MessagesSquare :size="18"/>{{item.title}}</button><button class="icon" :aria-label="item.pinned?'取消置顶':'置顶对话'" @click="pinItem('session',item)"><Pin :size="16"/></button></div><div v-if="!projectChats.length" class="empty-inline"><Folder :size="34"/><p>开始项目对话，或在已有对话顶部选择此项目。</p></div></section></div>

  </main>
 </div>
 <Teleport to="body">
  <div v-if="settingsOpen" class="settings-backdrop" @click.self="closeSettings">
   <section ref="settingsDialog" role="dialog" aria-modal="true" aria-label="工作空间设置" class="settings-dialog">
    <button class="icon settings-close" aria-label="关闭设置" @click="closeSettings"><X :size="22"/></button>
    <aside class="settings-sidebar"><h2>设置</h2><nav><button v-for="item in settingsNav" :key="item.id" :class="{active:settingsTab===item.id}" @click="navigate(item.id)"><component :is="item.icon" :size="19"/>{{item.id==='settings'?'模型与连接':item.label}}</button></nav><div class="settings-shortcuts"><button @click="navigate('home')"><LayoutDashboard :size="18"/>工作台</button><button @click="navigate('research')"><Workflow :size="18"/>研究任务</button><a href="/guide/project-guide.html" target="_blank" rel="noopener"><CircleHelp :size="18"/>使用说明</a></div></aside>
    <div class="settings-body"><div v-if="error" class="error-banner" role="alert">{{error}}<button class="icon" aria-label="关闭错误" @click="error=''"><X :size="16"/></button></div>
   <div v-if="settingsTab==='market'" class="content"><div class="page-heading"><div><h1>开源工具商店</h1><p>为你的智能体选择能力。启用状态保存在本地工作空间。</p></div><span class="outline-tag">已启用 {{marketTools.filter(t=>t.enabled).length}} / {{marketTools.length}}</span></div><section class="market-banner"><Globe :size="32"/><div><h2>让研究连接外面的世界</h2><p>默认自带联网文献、网页阅读、图片检索和 CSV 分析。</p></div><button class="button light" @click="navigate('tools')">打开工具实验室<ArrowRight :size="16"/></button></section><div class="market-filters"><div class="search-field"><Search :size="18"/><input v-model="marketSearch" aria-label="搜索工具" placeholder="搜索工具"/></div><button v-for="cat in ['全部','知识','联网','图像','分析','文件']" :key="cat" :class="{active:marketCategory===cat}" @click="marketCategory=cat">{{cat}}</button></div><div class="market-grid"><article v-for="t in visibleTools" :key="t.id" class="panel market-card"><div class="section-heading"><span class="feature-icon" :class="t.category==='联网'?'blue':t.category==='文件'?'peach':'mint'"><component :is="t.category==='联网'?Globe:t.category==='文件'?FolderPen:t.category==='图像'?ImageIcon:t.category==='分析'?Terminal:Network" :size="24"/></span><span class="pill" :class="t.enabled?'completed':''">{{t.locked?'核心能力':t.default?'默认自带':'可选工具'}}</span></div><h2>{{t.name}}</h2><p>{{t.description}}</p><div class="tool-permission">{{t.permission}}</div><div class="market-card-footer"><span>MCP · MIT</span><button class="button" :class="t.enabled?'light':'primary'" :disabled="t.locked||marketSaving===t.id" :aria-label="(t.enabled?'停用':'启用')+t.name" @click="toggleTool(t)">{{t.locked?'始终启用':t.enabled?'已启用 · 停用':'启用工具'}}</button></div></article></div><p v-if="!visibleTools.length" class="empty-inline">没有找到匹配的工具。</p><div class="info-note">问答 Agent 与工具实验室使用这里的选项；MCP 调用时检查最新开关。研究任务的知识检索始终可用。</div><section class="panel ecosystem"><h2>MCP 开源生态</h2><p>内置 7 个工具已有可运行适配器。以下链接用于查看官方源码，其他第三方服务器尚未安装。</p><a href="https://github.com/modelcontextprotocol/python-sdk" target="_blank" rel="noopener">MCP Python SDK<ExternalLink :size="16"/></a><a href="https://github.com/modelcontextprotocol/servers" target="_blank" rel="noopener">官方服务器示例<ExternalLink :size="16"/></a><button class="text-button" @click="navigate('settings')">查看 MCP 客户端配置<ArrowRight :size="16"/></button></section></div>
   <div v-else-if="settingsTab==='documents'" class="content"><div class="page-heading"><div><h1>你的青蟹知识资料库</h1><p>文献与业务资料，是每一个有依据的回答的起点。</p></div><label class="button primary upload-control"><LoaderCircle v-if="uploadBusy" class="spin" :size="16"/><Plus v-else :size="17"/>上传资料<input type="file" accept=".pdf,.txt,.md,.docx" :disabled="uploadBusy" @change="uploadDocument(($event.target as HTMLInputElement).files)"/></label></div><div class="library-summary"><div><Library :size="27"/><strong>{{docs.status_counts?.all??0}}<small>份资料</small></strong><p>项目内独立副本</p></div><div><span class="status-dot"/>已入库<strong>{{docs.status_counts?.processed??0}}</strong></div><div><span class="status-dot amber"/>处理中<strong>{{(docs.status_counts?.analyzing||0)+(docs.status_counts?.processing||0)+(docs.status_counts?.parsing||0)}}</strong></div><div><span class="status-dot red"/>历史失败<strong>{{docs.status_counts?.failed??0}}</strong></div></div><section class="panel"><div class="library-toolbar"><div class="search-field"><Search :size="17"/><input v-model="docSearch" placeholder="搜索本页资料名称" aria-label="搜索资料"/></div><select v-model="docStatus" @change="docPage=1;protect(loadDocs)" aria-label="资料状态"><option value="">全部状态</option><option value="processed">已入库</option><option value="failed">失败</option><option value="processing">处理中</option><option value="analyzing">分析中</option></select><button class="icon" title="刷新资料" @click="protect(loadDocs)"><RefreshCw :size="18"/></button></div><div class="table-scroll"><table><thead><tr><th>资料名称</th><th>入库状态</th><th>文本片段</th><th>更新时间</th><th>详情</th></tr></thead><tbody><tr v-for="d in filteredDocs" :key="d.id"><td><div class="document-name"><span class="file-icon"><FileText :size="21"/></span><span>{{basename(d.file_path)}}<small>{{Math.round(d.content_length/1000)}}k 字符 · {{d.id.slice(0,12)}}</small></span></div></td><td><span class="pill" :class="d.status">{{status(d.status)}}</span></td><td>{{d.chunks_count??'—'}}</td><td class="muted">{{new Date(d.updated_at).toLocaleDateString('zh-CN')}}</td><td><details class="doc-summary"><summary><ArrowUpRight :size="18"/></summary><p>{{d.content_summary}}</p><p v-if="d.error_msg">该资料存在历史处理错误，请在项目副本中检查。</p></details></td></tr></tbody></table><div v-if="!filteredDocs.length" class="empty-inline"><Library :size="32"/><p>{{loading?'正在加载资料…':'当前筛选没有资料'}}</p></div></div><div class="pagination"><span>共 {{docs.pagination?.total_count??0}} 份 · 第 {{docPage}} / {{docs.pagination?.total_pages||1}} 页</span><button class="icon" :disabled="!docs.pagination?.has_prev" @click="docPage--;protect(loadDocs)"><ChevronLeft :size="18"/></button><button class="icon" :disabled="!docs.pagination?.has_next" @click="docPage++;protect(loadDocs)"><ChevronRight :size="18"/></button></div></section><div class="info-note"><CheckCircle2 :size="18"/>新上传资料仅提交到项目副本 9622。原始 LightRAG 与原始知识库保持独立。</div></div>

   <div v-else-if="settingsTab==='graph'" class="content"><div class="page-heading"><div><h1>在关系中，发现知识</h1><p>按实体与关系层数查看子图；全库概览按连接度选取节点，不代表全量加载。</p></div><span class="outline-tag"><Network :size="16"/>{{graphData.nodes?.length||0}} 个展示节点</span></div><div class="graph-summary"><span>全库 <strong>{{graphStats.nodes?.toLocaleString()??'—'}}</strong> 个节点 · <strong>{{graphStats.edges?.toLocaleString()??'—'}}</strong> 条关系</span><span>当前展示 {{graphData.nodes?.length||0}} 个节点 · {{graphData.edges?.length||0}} 条关系</span></div><div class="graph-toolbar panel"><div class="search-field"><Search :size="17"/><input v-model="graphLabel" aria-label="图谱中心实体" placeholder="输入中心实体" @keydown.enter="protect(loadGraph)"/></div><select v-model="graphDepth" aria-label="关系深度"><option :value="1">1 层关系</option><option :value="2">2 层关系</option><option :value="3">3 层关系</option></select><select v-model="graphLimit" aria-label="节点展示上限"><option v-for="n in [65,150,300,500,1000]" :key="n" :value="n">最多 {{n}} 个节点</option></select><button class="button light" @click="graphLabel='*';protect(loadGraph)">全库概览</button><button class="button primary" @click="protect(loadGraph)">探索关联<ArrowRight :size="16"/></button><span>拖拽节点 · 滚轮缩放 · 点击查看详情</span></div><div class="label-chips"><span>热门实体</span><button v-for="label in graphLabels.slice(0,9)" :key="label" @click="graphLabel=label;protect(loadGraph)">{{label}}</button></div><div class="graph-layout"><div class="graph-canvas panel"><div ref="graphEl" class="graph-chart"/><div class="graph-legend"><span><i/>实体节点</span><span><i class="legend-line"/>资料中的关联</span><span>{{graphData.is_truncated?'已达到展示上限，可提高上限继续探索':'当前范围内未达到节点上限'}}</span></div><div v-if="!graphData.nodes?.length" class="graph-empty"><Network :size="38"/><p>没有找到该实体，请试试热门实体或其他名称。</p></div></div><aside class="panel node-detail"><div class="section-heading"><h3>实体笔记</h3><Network :size="18"/></div><template v-if="selectedNode"><span class="pill">{{selectedNode.properties?.entity_type||'知识实体'}}</span><h2>{{selectedNode.labels?.[0]||selectedNode.id}}</h2><div class="node-description">{{selectedNode.properties?.description}}</div><button class="button light full" @click="input=`介绍 ${selectedNode.labels?.[0]||selectedNode.id}，请根据知识库给出依据。`;navigate('chat')">围绕此实体提问<ArrowUpRight :size="16"/></button></template><div v-else class="evidence-empty"><Network :size="40"/><h4>连接，让资料更有价值</h4><p>点击图谱中的节点，查看实体描述，并继续发起有依据的问答。</p></div></aside></div></div>

   <div v-else-if="settingsTab==='tools'" class="content"><div class="page-heading"><div><h1>把研究能力，拆开看一看</h1><p>与智能体共享的研究工具，也可以单独执行并检查结果。</p></div><span class="outline-tag"><Wrench :size="16"/>6 类研究工具</span></div><div class="tools-grid"><button v-for="t in toolCatalog" :key="t.id" class="explore-card tool-card" :class="{selected:selectedTool===t.id}" @click="selectedTool=t.id;toolInput=t.example;toolJob=null"><span class="feature-icon" :class="t.color"><component :is="t.icon" :size="23"/></span><h3>{{t.label}}</h3><p>{{t.description}}</p><span class="card-link">{{!marketTools.find(m=>m.id===t.id)?.enabled?'已停用 · 商店可启用':selectedTool===t.id?'当前选择':'试试这个工具'}}<ArrowRight :size="14"/></span></button></div><div class="tool-run-layout"><section class="panel"><div class="section-heading"><h2>{{toolCatalog.find(t=>t.id===selectedTool)?.label}}</h2><span class="count-badge">INPUT</span></div><label class="field-label">{{selectedTool==='terminal'?'输入真实 CSV 记录':selectedTool==='download'||selectedTool==='webpage'?'输入允许研究站点的 HTTPS 地址':'输入检索词或笔记内容'}}</label><textarea class="tool-input" v-model="toolInput" aria-label="研究工具输入"/><div class="task-actions"><span class="muted">只操作公开资源与项目目录</span><button class="button primary" :disabled="toolBusy||busy||researchBusy||!toolInput.trim()||!marketTools.find(t=>t.id===selectedTool)?.enabled" @click="runTool"><LoaderCircle v-if="toolBusy" class="spin" :size="16"/><Play v-else :size="16"/>运行工具</button></div></section><section class="panel"><div class="section-heading"><h2>工具执行结果</h2><span v-if="toolJob" class="pill" :class="toolJob.status">{{status(toolJob.status)}}</span></div><div v-if="!toolJob" class="empty-inline"><Wrench :size="34"/><p>选择一个工具，查看真实调用结果。</p></div><div v-else-if="toolBusy" class="empty-inline"><LoaderCircle class="spin" :size="30"/><p>工具正在执行，请稍候…</p></div><template v-else-if="toolJob.result"><pre class="tool-output">{{JSON.stringify(toolJob.result.data,null,2)}}</pre><div class="tool-output-links" v-if="Array.isArray(toolJob.result.data)"><a v-for="(r,i) in toolJob.result.data" :key="i" :href="r.url||r.page_url" target="_blank" rel="noopener" class="text-button">{{r.title}}<ExternalLink :size="13"/></a></div><a v-if="toolJob.result.data?.artifact_id" :href="`/api/resources/${toolJob.result.data.artifact_id}?format=${toolJob.result.data.type==='markdown'?'md':'pdf'}`" class="button light"><Download :size="16"/>下载保存的资源</a><p class="muted">执行耗时 {{duration(toolJob.result.metrics.elapsed_ms)}}</p></template><div v-else class="empty-inline"><CircleHelp :size="30"/><p>执行未获得结果，可检查输入与网络后重试。</p></div></section></div><div class="info-note"><CircleHelp :size="18"/>公开书目与参考图片用于发现资料；正文结论需核实。网页抓取和下载仅允许 FAO、NCBI、PLOS、Wikipedia、Wikimedia。</div></div>

   <div v-else-if="settingsTab==='metrics'" class="content"><div class="page-heading"><div><h1>看见每次运行的过程</h1><p>记录真实耗时、Token 使用与工具调用，定位检索和生成环节。</p></div><button class="button light" @click="navigate('metrics')"><RefreshCw :size="16"/>刷新记录</button></div><section class="stat-grid"><div class="stat-card"><span class="stat-icon mint"><Activity :size="20"/></span><div><span>问答记录</span><strong>{{metrics.length}}</strong></div></div><div class="stat-card"><span class="stat-icon blue"><Clock3 :size="20"/></span><div><span>平均响应</span><strong class="stat-word">{{metrics.length?duration(metrics.reduce((a,m)=>a+m.elapsed_ms,0)/metrics.length):'—'}}</strong></div></div><div class="stat-card"><span class="stat-icon peach"><Braces :size="20"/></span><div><span>累计输入 Token</span><strong class="stat-word">{{metrics.reduce((a,m)=>a+(m.input_tokens||0),0).toLocaleString()}}</strong></div></div><div class="stat-card"><span class="stat-icon lavender"><Workflow :size="20"/></span><div><span>任务总数</span><strong>{{jobs.length}}</strong></div></div></section><section class="panel"><div class="section-heading"><h2>问答性能记录</h2><span class="muted">最多显示最近 100 次</span></div><div class="table-scroll"><table><thead><tr><th>运行编号</th><th>检索模式</th><th>总耗时</th><th>检索耗时</th><th>首字耗时</th><th>输入 / 输出 Token</th><th>工具调用</th></tr></thead><tbody><tr v-for="m in metrics" :key="m.run_id"><td class="mono">{{m.run_id.slice(0,8)}}</td><td><span class="pill">{{m.mode}}</span></td><td>{{duration(m.elapsed_ms)}}</td><td>{{duration(m.retrieval_ms)}}</td><td>{{duration(m.first_token_ms)}}</td><td>{{m.input_tokens||0}} / {{m.output_tokens||0}}</td><td>{{m.tool_calls?.join(', ')||'—'}}</td></tr></tbody></table></div><div v-if="!metrics.length" class="empty-inline"><Activity :size="32"/><p>完成一次问答后，真实运行数据会出现在这里。</p></div></section><div class="info-note"><CircleHelp :size="18"/>这些是运行性能指标。引用编号检查不等于语义正确率，问答准确性仍需业务评审。</div></div>

   <div v-else class="content"><div class="page-heading"><div><h1>连接与运行配置</h1><p>模型、知识库与持久化记忆，组成你的研究工作空间。</p></div><span class="outline-tag"><span class="status-dot"/>本地运行</span></div><div class="settings-grid"><section class="panel setting-card model-form"><h2>模型配置</h2><p>支持 OpenAI 兼容接口，自定义回答与图像模型。</p><label>服务模板<select v-model="presetId" aria-label="模型服务模板" @change="usePreset"><option v-for="p in presets" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>接口地址<input v-model="modelDraft.base_url" aria-label="模型接口地址" placeholder="https://your-provider.example/v1"/></label><label>回答模型<input v-model="modelDraft.model" aria-label="回答模型名称" placeholder="输入支持工具调用的模型名称"/></label><label>图像模型<input v-model="modelDraft.vision_model" aria-label="图像模型名称" placeholder="输入支持图片的模型名称"/></label><label>API Key<input v-model="modelDraft.api_key" aria-label="模型 API Key" type="password" autocomplete="new-password" :placeholder="config.key_configured&&modelDraft.base_url===config.base_url?'已配置；留空保留当前凭据':'填写该服务的 API Key'"/></label><div class="model-actions"><span class="pill" :class="config.key_configured?'completed':'failed'">{{config.key_configured&&modelDraft.base_url===config.base_url?'当前接口凭据已配置':'需要配置该接口凭据'}}</span><button class="button primary" :disabled="modelSaving" @click="saveModel">{{modelSaving?'保存中…':'保存配置'}}</button></div><p class="model-note">用于应用回答、规划与图片观察。LightRAG 内部抽取和嵌入沿用副本配置；切换接口需填写对应密钥。</p><a v-if="presets.find(p=>p.id===presetId)?.docs" class="text-button" :href="presets.find(p=>p.id===presetId)?.docs" target="_blank" rel="noopener">服务官方文档<ExternalLink :size="15"/></a></section><section class="panel setting-card"><span class="feature-icon peach"><Network :size="24"/></span><h2>LightRAG 知识库</h2><p>保留原始知识库，应用使用独立迁移副本。</p><div class="retrieval-setting"><div><h3>启用知识图谱</h3><p>开启时结合图谱与原文，关闭时仅检索原文。对新任务生效。</p></div><button class="setting-switch" role="switch" aria-label="启用知识图谱" :aria-checked="!!config.knowledge_graph_enabled" :class="{enabled:config.knowledge_graph_enabled}" :disabled="graphSaving" @click="toggleGraph"><span/></button></div><dl><dt>副本接口</dt><dd>{{config.lightrag_url}}</dd><dt>检索方式</dt><dd>{{config.knowledge_graph_enabled?'图谱与原文':'仅原文'}}</dd><dt>记忆存储</dt><dd>{{config.memory}}</dd><dt>研究引擎</dt><dd>{{config.task_engine}}</dd></dl><a href="http://127.0.0.1:9622/webui/" target="_blank" rel="noopener" class="text-button">打开副本管理界面<ExternalLink :size="15"/></a></section><section class="panel setting-card wide"><div class="section-heading"><div><h2>让其他智能体调用青蟹知识工具</h2></div><span class="outline-tag">MCP · stdio</span></div><p>提供知识检索、联网文献、网页阅读、图片检索、CSV 分析、PDF 下载和笔记，共 7 个工具。将以下配置加入支持 MCP 的客户端。</p><pre>{{mcpConfig}}</pre><div class="tool-tags"><span>search_crab_knowledge</span><span>analyze_pond_csv</span><span>search_reference_images</span><span>search_public_literature</span><span>fetch_research_page</span><span>download_research_pdf</span><span>save_note</span><span>crabgraph://capabilities</span></div></section></div></div>
    </div>
   </section>
  </div>
 </Teleport>

</template>
